begin;
with j as (select * from jsonb_to_recordset($law7d0038$[{"code_id":"GK_RF_2","article_number":"893","version_date":"1994-11-30","article_text":"1. При необходимости изменения условий хранения вещи, предусмотренных договором хранения, хранитель обязан незамедлительно уведомить об этом поклажедателя и дождаться его ответа.\n\nЕсли изменение условий хранения необходимо для устранения опасности утраты, недостачи или повреждения вещи, хранитель вправе изменить способ, место и иные условия хранения, не дожидаясь ответа поклажедателя.\n\n2. Если во время хранения возникла реальная угроза порчи вещи, либо вещь уже подверглась порче, либо возникли обстоятельства, не позволяющие обеспечить ее сохранность, а своевременного принятия мер от поклажедателя ожидать нельзя, хранитель вправе самостоятельно продать вещь или часть ее по цене, сложившейся в месте хранения. Если указанные обстоятельства возникли по причинам, за которые хранитель не отвечает, он имеет право на возмещение своих расходов на продажу за счет покупной цены.","article_title":"Статья 893. Изменение условий хранения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19d92da7fd81e90f3bf1a7ea34b6757e1f9cfdf92fd7285355614b4744401b04"},{"code_id":"GK_RF_2","article_number":"894","version_date":"1994-11-30","article_text":"1. Вещи, легковоспламеняющиеся, взрывоопасные или вообще опасные по своей природе, если поклажедатель при их сдаче на хранение не предупредил хранителя об этих свойствах, могут быть в любое время обезврежены или уничтожены хранителем без возмещения поклажедателю убытков. Поклажедатель отвечает за убытки, причиненные в связи с хранением таких вещей хранителю и третьим лицам.\n\nПри передаче вещей с опасными свойствами на хранение профессиональному хранителю правила, предусмотренные абзацем первым настоящего пункта, применяются в случае, когда такие вещи были сданы на хранение под неправильным наименованием и хранитель при их принятии не мог путем наружного осмотра удостовериться\n\nв их опасных свойствах.\n\nПри возмездном хранении в случаях, предусмотренных настоящим пунктом, уплаченное вознаграждение за хранение вещей не возвращается, а если оно не было уплачено, хранитель может взыскать его полностью.\n\n2. Если принятые на хранение с ведома и согласия хранителя вещи, указанные в абзаце первом пункта 1 настоящей статьи, стали, несмотря на соблюдение условий их хранения, опасными для окружающих либо для имущества хранителя или третьих лиц и обстоятельства не позволяют хранителю потребовать от поклажедателя немедленно их забрать либо он не выполняет это требование, эти вещи могут быть обезврежены или уничтожены хранителем без возмещения поклажедателю убытков. Поклажедатель не несет в таком случае ответственности перед хранителем и третьими лицами за убытки, причиненные в связи с хранением этих вещей.","article_title":"Статья 894. Хранение вещей с опасными свойствами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be17a3a7d89443a19de362529428ba14b6f8fde0515a6b2b56197cf0bf65c95a"},{"code_id":"GK_RF_2","article_number":"895","version_date":"1994-11-30","article_text":"Если договором хранения не предусмотрено иное, хранитель не вправе без согласия поклажедателя передавать вещь на хранение третьему лицу, за исключением случаев, когда он вынужден к этому силою обстоятельств в интересах поклажедателя и лишен возможности получить его согласие.\n\nО передаче вещи на хранение третьему лицу хранитель обязан незамедлительно уведомить поклажедателя.\n\nПри передаче вещи на хранение третьему лицу условия договора между поклажедателем и первоначальным хранителем сохраняют силу и последний отвечает за действия третьего лица, которому он передал вещь на хранение, как за свои собственные.","article_title":"Статья 895. Передача вещи на хранение третьему лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdb5382826c16575a97feb2df79e236381e79f95a81a1c74c2a84cf6a6c76af7"},{"code_id":"GK_RF_2","article_number":"896","version_date":"1994-11-30","article_text":"1. Вознаграждение за хранение должно быть уплачено хранителю по окончании хранения, а если оплата хранения предусмотрена по периодам, оно должно выплачиваться соответствующими частями по истечении каждого периода.\n\n2. При просрочке уплаты вознаграждения за хранение более чем на половину периода, за который оно должно быть уплачено, хранитель вправе отказаться от исполнения договора и потребовать от поклажедателя немедленно забрать сданную на хранение вещь.\n\n3. Если хранение прекращается до истечения обусловленного срока по обстоятельствам, за которые хранитель не отвечает, он имеет право на соразмерную часть вознаграждения, а в случае, предусмотренном пунктом 1 статьи 894 настоящего Кодекса, на всю сумму вознаграждения.\n\nЕсли хранение прекращается досрочно по обстоятельствам, за которые хранитель отвечает, он не вправе требовать вознаграждение за хранение, а полученные в счет этого вознаграждения суммы должен вернуть поклажедателю.\n\n4. Если по истечении срока хранения находящаяся на хранении вещь не взята обратно поклажедателем, он обязан уплатить хранителю соразмерное вознаграждение за дальнейшее хранение вещи. Это правило применяется и в случае, когда поклажедатель обязан забрать вещь до истечения срока хранения.\n\n5. Правила настоящей статьи применяются, если договором хранения не предусмотрено иное.","article_title":"Статья 896. Вознаграждение за хранение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c5b9becfbc4369ad221809ff38ec702350bfe7aa83067fa53256fca26754b85"},{"code_id":"GK_RF_2","article_number":"897","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором хранения, расходы хранителя на хранение вещи включаются в вознаграждение за хранение.\n\n2. При безвозмездном хранении поклажедатель обязан возместить хранителю произведенные им необходимые расходы на хранение вещи, если законом или договором хранения не предусмотрено иное.","article_title":"Статья 897. Возмещение расходов на хранение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3958b5bcc2e951c4e873e02fb93de573cd2743d8ae7cb662a58d9c4d9fad6d9"},{"code_id":"GK_RF_2","article_number":"898","version_date":"1994-11-30","article_text":"1. Расходы на хранение вещи, которые превышают обычные расходы такого рода и которые стороны не могли предвидеть при заключении договора хранения (чрезвычайные расходы), возмещаются хранителю, если поклажедатель дал согласие на эти расходы или одобрил их впоследствии, а также в других случаях, предусмотренных законом, иными правовыми актами или договором.\n\n2. При необходимости произвести чрезвычайные расходы хранитель обязан запросить поклажедателя о согласии на эти расходы. Если поклажедатель не сообщит о своем несогласии в срок, указанный хранителем, или в течение нормально необходимого для ответа времени, считается, что он согласен на чрезвычайные расходы.\n\nВ случае, когда хранитель произвел чрезвычайные расходы на хранение, не получив от поклажедателя предварительного согласия на эти расходы, хотя по обстоятельствам дела это было возможно, и поклажедатель впоследствии не одобрил их, хранитель может требовать возмещения чрезвычайных расходов лишь в пределах ущерба, который мог быть причинен вещи, если бы эти расходы не были произведены.\n\n3. Если иное не предусмотрено договором хранения, чрезвычайные расходы возмещаются сверх вознаграждения за хранение.","article_title":"Статья 898. Чрезвычайные расходы на хранение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f58604b04a23145f3b501c7505792e36cbb149bc672bc84aa8cf58f3363c90f"},{"code_id":"GK_RF_2","article_number":"899","version_date":"1994-11-30","article_text":"1. По истечении обусловленного срока хранения или срока, предоставленного хранителем для обратного получения вещи на основании пункта 3 статьи 889 настоящего Кодекса, поклажедатель обязан немедленно забрать переданную на хранение вещь.\n\nСумма, вырученная от продажи вещи, передается поклажедателю за вычетом сумм, причитающихся хранителю, в том числе его расходов на продажу вещи.","article_title":"Статья 899. Обязанность поклажедателя взять вещь обратно","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c87771a9325e051740c0ecac14473b4de9b8f3c58a126df5f0bc6e745e797d07"},{"code_id":"GK_RF_2","article_number":"900","version_date":"1994-11-30","article_text":"1. Хранитель обязан возвратить поклажедателю или лицу, указанному им в качестве получателя, ту самую вещь, которая была передана на хранение, если договором не предусмотрено хранение с обезличением (статья 890).\n\n2. Вещь должна быть возвращена хранителем в том состоянии, в каком она была принята на хранение, с учетом ее естественного ухудшения, естественной убыли или иного изменения вследствие ее естественных свойств.\n\n3. Одновременно с возвратом вещи хранитель обязан передать плоды и доходы, полученные за время ее хранения, если иное не предусмотрено договором хранения.","article_title":"Статья 900. Обязанность хранителя возвратить вещь","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed97cada938786767529693eeb4201affbb2e5a98c90b036db1a9335618d8a2c"},{"code_id":"GK_RF_2","article_number":"901","version_date":"1994-11-30","article_text":"1. Хранитель отвечает за утрату, недостачу или повреждение вещей, принятых на хранение, по основаниям, предусмотренным статьей 401 настоящего Кодекса.\n\nПрофессиональный хранитель отвечает за утрату, недостачу или повреждение вещей, если не докажет, что утрата, недостача или повреждение произошли вследствие непреодолимой силы, либо из-за свойств вещи, о которых хранитель, принимая ее на хранение, не знал и не должен был знать, либо в результате умысла или грубой неосторожности поклажедателя.\n\n2. За утрату, недостачу или повреждение принятых на хранение вещей после того, как наступила обязанность поклажедателя взять эти вещи обратно (пункт 1 статьи 899), хранитель отвечает лишь при наличии с его стороны умысла или грубой неосторожности.","article_title":"Статья 901. Основания ответственности хранителя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ecd5f7d7fab52ff6371090fbda2fa9f5bd27cab2e602952c249e437196866de1"},{"code_id":"GK_RF_2","article_number":"902","version_date":"1994-11-30","article_text":"1. Убытки, причиненные поклажедателю утратой, недостачей или повреждением вещей, возмещаются хранителем в соответствии со статьей 393 настоящего Кодекса, если законом или договором хранения не предусмотрено иное.\n\n2. При безвозмездном хранении убытки, причиненные поклажедателю утратой, недостачей или повреждением вещей, возмещаются:\n\n1) за утрату и недостачу вещей - в размере стоимости утраченных или недостающих вещей;\n\n2) за повреждение вещей - в размере суммы, на которую понизилась их стоимость.\n\n3. В случае, когда в результате повреждения, за которое хранитель отвечает, качество вещи изменилось настолько, что она не может быть использована по первоначальному назначению, поклажедатель вправе от нее отказаться и потребовать от хранителя возмещения стоимости этой вещи, а также других убытков, если иное не предусмотрено законом или договором хранения.","article_title":"Статья 902. Размер ответственности хранителя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0fd50e4fd73215964d2a3b931a76e4bbd51ed1365f183d61450775608aeb51bd"},{"code_id":"GK_RF_2","article_number":"903","version_date":"1994-11-30","article_text":"Поклажедатель обязан возместить хранителю убытки, причиненные свойствами сданной на хранение вещи, если хранитель, принимая вещь на хранение, не знал и не должен был знать об этих свойствах.","article_title":"Статья 903. Возмещение убытков, причиненных хранителю","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f65d420db3a8c5f56df9d05e61b6498e33d78eb64014ceddcb0ced1ae2ae5da3"},{"code_id":"GK_RF_2","article_number":"904","version_date":"1994-11-30","article_text":"Хранитель обязан по первому требованию поклажедателя возвратить принятую на хранение вещь, хотя бы предусмотренный договором срок ее хранения еще не окончился.","article_title":"Статья 904. Прекращение хранения по требованию поклажедателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"609d4e82d6b98e368156b85a7aff4f9e78fdf14479e9235415547d9a6049b37a"},{"code_id":"GK_RF_2","article_number":"905","version_date":"1994-11-30","article_text":"Общие положения о хранении (статьи 886 - 904) применяются к отдельным его видам, если правилами об отдельных видах хранения, содержащимися в статьях 907 - 926 настоящего Кодекса и в других законах, не установлено иное.","article_title":"Статья 905. Применение общих положений о хранении к отдельным его видам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"67af3da5cd694894ed309ad6fa429588bd4dba2fd97c4fc9c997d956700f0b67"},{"code_id":"GK_RF_2","article_number":"906","version_date":"1994-11-30","article_text":"Правила настоящей главы применяются к обязательствам хранения, возникающим в силу закона, если законом не установлены иные правила.","article_title":"Статья 906. Хранение в силу закона","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c73cd53a6b2565cd07d61865df741a02aff217d933267f9bece2a982bd43595e"},{"code_id":"GK_RF_2","article_number":"907","version_date":"1994-11-30","article_text":"1. По договору складского хранения товарный склад (хранитель) обязуется за вознаграждение хранить товары, переданные ему товаровладельцем (поклажедателем), и возвратить эти товары в сохранности.\n\nТоварным складом признается организация, осуществляющая в качестве предпринимательской деятельности хранение товаров и оказывающая связанные с хранением услуги.\n\n2. Письменная форма договора складского хранения считается соблюденной, если его заключение и принятие товара на склад удостоверены складским документом (статья 912).","article_title":"Статья 907. Договор складского хранения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5cab35ae5d9b0a8542261123747ee4ea26db737954cb9f52c0301a6e3f05a149"},{"code_id":"GK_RF_2","article_number":"909","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором складского хранения, товарный склад при приеме товаров на хранение обязан за свой счет произвести осмотр товаров и определить их количество (число единиц или товарных мест либо меру - вес, объем) и внешнее состояние.\n\n2. Товарный склад обязан предоставлять товаровладельцу во время хранения возможность осматривать товары или их образцы, если хранение осуществляется с обезличением, брать пробы и принимать меры, необходимые для обеспечения сохранности товаров.","article_title":"Статья 909. Проверка товаров при их приеме товарным складом и во время хранения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6eaa3b5783ec2f25cc8dd47389ee6c10cd1bcc93aa439946f633425f35314725"},{"code_id":"GK_RF_2","article_number":"910","version_date":"1994-11-30","article_text":"1. В случае, когда для обеспечения сохранности товаров требуется изменить условия их хранения, товарный склад вправе принять требуемые меры самостоятельно. Однако он обязан уведомить товаровладельца о принятых мерах, если требовалось существенно изменить условия хранения товаров, предусмотренные договором складского хранения.\n\n2. При обнаружении во время хранения повреждений товара, выходящих за пределы согласованных в договоре складского хранения или обычных норм естественной порчи, товарный склад обязан незамедлительно составить об этом акт и в тот же день известить товаровладельца.","article_title":"Статья 910. Изменение условий хранения и состояния товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27f9c680d8e7942b953a46f1bd582444828543073b5bafdf6f4ccf39031e21c2"},{"code_id":"GK_RF_2","article_number":"911","version_date":"1994-11-30","article_text":"1. Товаровладелец и товарный склад имеют право каждый требовать при возвращении товара его осмотра и проверки его количества. Вызванные этим расходы несет тот, кто потребовал осмотра товара или проверки его количества.\n\n2. Если при возвращении товара складом товаровладельцу товар не был ими совместно осмотрен или проверен, заявление о недостаче или повреждении товара вследствие его ненадлежащего хранения должно быть сделано складу письменно при получении товара, а в отношении недостачи или повреждения, которые не могли быть обнаружены при обычном способе принятия товара, в течение трех дней по его получении.\n\nПри отсутствии заявления, указанного в абзаце первом настоящего пункта, считается, если не доказано иное, что товар возвращен складом в соответствии с условиями договора складского хранения.","article_title":"Статья 911. Проверка количества и состояния товара при возвращении его товаровладельцу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef30f41d4413310a9f701c5d9ceb62492371a3beb4e195b7ebff6995a7b08870"},{"code_id":"GK_RF_2","article_number":"912","version_date":"1994-11-30","article_text":"1. Товарный склад выдает в подтверждение принятия товара на хранение один из следующих складских документов:\n\nдвойное складское свидетельство;\n\nпростое складское свидетельство;\n\nскладскую квитанцию.\n\n2. Двойное складское свидетельство состоит из двух частей - складского свидетельства и залогового свидетельства (варранта), которые могут быть отделены одно от другого.\n\n3. Двойное складское свидетельство, каждая из двух его частей и простое складское свидетельство являются ценными бумагами.\n\n4. Товар, принятый на хранение по двойному или простому складскому свидетельству, может быть в течение его хранения предметом залога путем залога соответствующего свидетельства.","article_title":"Статья 912. Складские документы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbabc6dcda4bcf675f9f06f4def3a1ea1cbb685cd1f6eb7b3a585b28af837803"},{"code_id":"GK_RF_2","article_number":"913","version_date":"1994-11-30","article_text":"1. В каждой части двойного складского свидетельства должны быть одинаково указаны:\n\n1) наименование и место нахождения товарного склада, принявшего товар на хранение;\n\n2) текущий номер складского свидетельства по реестру склада;\n\n3) наименование юридического лица либо имя гражданина, от которого принят товар на хранение, а также место нахождения (место жительства) товаровладельца;\n\n4) наименование и количество принятого на хранение товара - число единиц и (или) товарных мест и (или) мера (вес, объем) товара;\n\n5) срок, на который товар принят на хранение, если такой срок устанавливается, либо указание, что товар принят на хранение до востребования;\n\n6) размер вознаграждения за хранение либо тарифы, на основании которых он исчисляется, и порядок оплаты хранения;\n\n7) дата выдачи складского свидетельства.\n\nОбе части двойного складского свидетельства должны иметь идентичные подписи уполномоченного лица и печати товарного склада (при наличии печатей). (В редакции Федерального закона от 06.04.2015 № 82-ФЗ)\n\n2. Документ, не соответствующий требованиям настоящей статьи, не является двойным складским свидетельством.","article_title":"Статья 913. Двойное складское свидетельство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7a9a6af80efa0b4c923171944e059065b9c8f888f4559685b0a75a9129dd0570"},{"code_id":"GK_RF_2","article_number":"914","version_date":"1994-11-30","article_text":"1. Держатель складского и залогового свидетельств имеет право распоряжения хранящимся на складе товаром в полном объеме.\n\n2. Держатель складского свидетельства, отделенного от залогового свидетельства, вправе распоряжаться товаром, но не может взять его со склада до погашения кредита, выданного по залоговому свидетельству.\n\n3. Держатель залогового свидетельства, иной, чем держатель складского свидетельства, имеет право залога на товар в размере выданного по залоговому свидетельству кредита и процентов по нему. При залоге товара об этом делается отметка на складском свидетельстве.","article_title":"Статья 914. Права держателей складского и залогового свидетельств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89f961caf5348c60da0acbbcb626033a900047beaf74d38520b1a5cfe42c11c9"},{"code_id":"GK_RF_2","article_number":"915","version_date":"1994-11-30","article_text":"Складское свидетельство и залоговое свидетельство могут передаваться вместе или порознь по передаточным надписям.","article_title":"Статья 915. Передача складского и залогового свидетельств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"972e622e845577cd98e86010b7c7f22065482c5e9dad7c5591e0d2a947ae846f"},{"code_id":"GK_RF_2","article_number":"916","version_date":"1994-11-30","article_text":"1. Товарный склад выдает товар держателю складского и залогового свидетельств (двойного складского свидетельства) не иначе как в обмен на оба эти свидетельства вместе.\n\n2. Держателю складского свидетельства, который не имеет залогового свидетельства, но внес сумму долга по нему, товар выдается складом не иначе как в обмен на складское свидетельство и при условии представления вместе с ним квитанции об уплате всей суммы долга по залоговому свидетельству.\n\n3. Товарный склад, вопреки требованиям настоящей статьи выдавший товар держателю складского свидетельства, не имеющему залогового свидетельства и не внесшему сумму долга по нему, несет ответственность перед держателем залогового свидетельства за платеж всей обеспеченной по нему суммы.\n\n4. Держатель складского и залогового свидетельств вправе требовать выдачи товара по частям. При этом в обмен на первоначальные свидетельства ему выдаются новые свидетельства на товар, оставшийся на складе.","article_title":"Статья 916. Выдача товара по двойному складскому свидетельству","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"56a12dd67e0de2a14c11fbc472bb3866f13875660973a60bcd8041632159f822"},{"code_id":"GK_RF_2","article_number":"917","version_date":"1994-11-30","article_text":"1. Простое складское свидетельство выдается на предъявителя.\n\n2. Простое складское свидетельство должно содержать сведения, предусмотренные подпунктами 1, 2, 4 - 7 пункта 1 и последним абзацем статьи 913 настоящего Кодекса, а также указание на то, что оно выдано на предъявителя.\n\n3. Документ, не соответствующий требованиям настоящей статьи, не является простым складским свидетельством.","article_title":"Статья 917. Простое складское свидетельство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"39afb97a7dfdcdb4c4459966eebde7fdc181c454e6251ecf113f42dfc7ad3b76"},{"code_id":"GK_RF_2","article_number":"918","version_date":"1994-11-30","article_text":"Если из закона, иных правовых актов или договора следует, что товарный склад может распоряжаться сданными ему на хранение товарами, к отношениям сторон применяются правила главы 42 настоящего Кодекса о займе, однако время и место возврата товаров определяются правилами настоящей главы.","article_title":"Статья 918. Хранение вещей с правом распоряжения ими","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ead4b424e9d9acdfb3a5cbab56d8dff1b132376fdc9c0caad8937b3a217e7cf0"},{"code_id":"GK_RF_2","article_number":"919","version_date":"1994-11-30","article_text":"1. Договор хранения в ломбарде вещей, принадлежащих гражданину, является публичным договором (статья 426).\n\n2. Заключение договора хранения в ломбарде удостоверяется выдачей ломбардом поклажедателю именной сохранной квитанции.\n\n3. Вещь, сдаваемая на хранение в ломбард, подлежит оценке по соглашению сторон в соответствии с ценами на вещи такого рода и качества, обычно устанавливаемыми в торговле в момент и в месте их принятия на хранение.\n\n4. Ломбард обязан страховать в пользу поклажедателя за свой счет принятые на хранение вещи в полной сумме их оценки, произведенной в соответствии с пунктом 3 настоящей статьи.","article_title":"Статья 919. Хранение в ломбарде","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"60715ec28bd9bb3dfc2e29b02916ec4a8ab23c17e024d4c30a407d838f28a7a5"},{"code_id":"GK_RF_2","article_number":"920","version_date":"1994-11-30","article_text":"1. Если вещь, сданная на хранение в ломбард, не востребована поклажедателем в обусловленный соглашением с ломбардом срок, ломбард обязан хранить ее в течение двух месяцев с взиманием за это платы, предусмотренной договором хранения. По истечении этого срока невостребованная вещь может быть продана ломбардом в порядке, установленном пунктом 5 статьи 358 настоящего Кодекса.","article_title":"Статья 920. Не востребованные из ломбарда вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d92e41144d77001035385dd795cc3f73a634eaec9dd405f927e6d4aaddd8a0fe"},{"code_id":"GK_RF_2","article_number":"921","version_date":"1994-11-30","article_text":"1. Банк может принимать на хранение ценные бумаги, драгоценные металлы и камни, иные драгоценные вещи и другие ценности, в том числе документы.\n\n2. Заключение договора хранения ценностей в банке удостоверяется выдачей банком поклажедателю именного сохранного документа, предъявление которого является основанием для выдачи хранимых ценностей поклажедателю.","article_title":"Статья 921. Хранение ценностей в банке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4abd7555c3057661fea011de5fa745c37962a9471ccf79fd8e80313a9b51e01"},{"code_id":"GK_RF_2","article_number":"922","version_date":"1994-11-30","article_text":"1. Договором хранения ценностей в банке может быть предусмотрено их хранение с использованием поклажедателем (клиентом) или с предоставлением ему охраняемого банком индивидуального банковского сейфа (ячейки сейфа, изолированного помещения в банке).\n\nПо договору хранения ценностей в индивидуальном банковском сейфе клиенту предоставляется право самому помещать ценности в сейф и изымать их из сейфа, для чего ему должны быть выданы ключ от сейфа, карточка, позволяющая идентифицировать клиента, либо иной знак или документ, удостоверяющие право клиента на доступ к сейфу и его содержимому.\n\nУсловиями договора может быть предусмотрено право клиента работать в банке с ценностями, хранимыми в индивидуальном сейфе.\n\n2. По договору хранения ценностей в банке с использованием клиентом индивидуального банковского се\n\nйфа банк принимает от клиента ценности, которые должны храниться в сейфе, осуществляет контроль за их помещением клиентом в сейф и изъятием из сейфа и после изъятия возвращает их клиенту.\n\n3. По договору хранения ценностей в банке с предоставлением клиенту индивидуального банковского сейфа банк обеспечивает клиенту возможность помещения ценностей в сейф и изъятия их из сейфа вне чьего-либо контроля, в том числе и со стороны банка.\n\nБанк обязан осуществлять контроль за доступом в помещение, где находится предоставленный клиенту сейф.\n\nЕсли договором хранения ценностей в банке с предоставлением клиенту индивидуального банковского сейфа не предусмотрено иное, банк освобождается от ответственности за несохранность содержимого сейфа, если докажет, что по условиям хранения доступ кого-либо к сейфу без ведома клиента был невозможен либо стал возможным вследствие непреодолимой силы.\n\n4. К договору о предоставлении банковского сейфа в пользование другому лицу без ответственности банка за содержимое сейфа применяются правила настоящего Кодекса о договоре аренды.","article_title":"Статья 922. Хранение ценностей в индивидуальном банковском сейфе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e091fb40eee968f9020ba05ae92fde968fd5e017496ac1bd172438c0ee999b0f"},{"code_id":"GK_RF_2","article_number":"923","version_date":"1994-11-30","article_text":"1. Находящиеся в ведении транспортных организаций общего пользования камеры хранения обязаны принимать на хранение вещи пассажиров и других граждан независимо от наличия у них проездных документов. Договор хранения вещей в камерах хранения транспортных организаций признается публичным договором (статья 426).\n\n2. В подтверждение принятия вещи на хранение в камеру хранения (за исключением автоматических камер) поклажедателю выдается квитанция или номерной жетон. В случае утраты квитанции или жетона сданная в камеру хранения вещь выдается поклажедателю по представлении доказательств принадлежности ему этой вещи.\n\n3. Срок, в течение которого камера хранения обязана хранить вещи, определяется правилами, установленными в соответствии с абзацем вторым пункта 2 статьи 784 настоящего Кодекса, если соглашением сторон не установлен более длительный срок. Вещи, не востребованные в указанные сроки, камера хранения обязана хранить еще в течение тридцати дней. По истечении этого срока невостребованные вещи могут быть проданы в порядке, предусмотренном пунктом 2 статьи 899 настоящего Кодекса.\n\n4. Убытки поклажедателя вследствие утраты, недостачи или повреждения вещей, сданных в камеру хранения, в пределах суммы их оценки поклажедателем при сдаче на хранение подлежат возмещению хранителем в течение двадцати четырех часов с момента предъявления требования об их возмещении.","article_title":"Статья 923. Хранение в камерах хранения транспортных организаций","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d259928cfc8a26272186d3e700566cf7c501abdf577eb5aafadce8d55fe84cb4"},{"code_id":"GK_RF_2","article_number":"924","version_date":"1994-11-30","article_text":"1. Хранение в гардеробах организаций предполагается безвозмездным, если вознаграждение за хранение не оговорено или иным очевидным способом не обусловлено при сдаче вещи на хранение.\n\nХранитель вещи, сданной в гардероб, независимо от того, осуществляется хранение возмездно или безвозмездно, обязан принять для обеспечения сохранности вещи все меры, предусмотренные пунктами 1 и 2 статьи 891 настоящего Кодекса.\n\n2. Правила настоящей статьи применяются также к хранению верхней одежды, головных уборов и иных подобных вещей, оставляемых без сдачи их на хранение гражданами в местах, отведенных для этих целей в организациях и средствах транспорта.","article_title":"Статья 924. Хранение в гардеробах организаций","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"95bb6642773bfcc90a25f7bfbf23d227c2453cfc9d4d23dee00e1452d6b18be8"},{"code_id":"GK_RF_2","article_number":"925","version_date":"1994-11-30","article_text":"1. Гостиница отвечает как хранитель и без особого о том соглашения с проживающим в ней лицом (постояльцем) за утрату, недостачу или повреждение его вещей, внесенных в гостиницу, за исключением денег, иных валютных ценностей, ценных бумаг и других драгоценных вещей.\n\nВнесенной в гостиницу считается вещь, вверенная работникам гостиницы, либо вещь, помещенная в гостиничном номере или ином предназначенном для этого месте.\n\n2. Гостиница отвечает за утрату денег, иных валютных ценностей, ценных бумаг и других драгоценных вещей постояльца при условии, если они были приняты гостиницей на хранение либо были помещены постояльцем в предоставленный ему гостиницей индивидуальный сейф независимо от того, находится этот сейф в его номере или в ином помещении гостиницы. Гостиница освобождается от ответственности за несохранность содержимого такого сейфа, если докажет, что по условиям хранения доступ кого-либо к сейфу без ведома постояльца был невозможен либо стал возможным вследствие непреодолимой силы.\n\n3. Постоялец, обнаруживший утрату, недостачу или повреждение своих вещей, обязан без промедления заявить об этом администрации гостиницы. В противном случае гостиница освобождается от ответственности за несохранность вещей.\n\n4. Сделанное гостиницей объявление о том, что она не принимает на себя ответственности за несохранность вещей постояльцев, не освобождает ее от ответственности.\n\n5. Правила настоящей статьи соответственно применяются в отношении хранения вещей граждан в мотелях, домах отдыха, пансионатах, санаториях, банях и других подобных организациях.","article_title":"Статья 925. Хранение в гостинице","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"536ff6c68726ca3a79bddd61ea32c839156d48324da7cbcaec573a6ac5248abe"},{"code_id":"GK_RF_2","article_number":"926","version_date":"1994-11-30","article_text":"1. По договору о секвестре двое или несколько лиц, между которыми возник спор о праве на вещь, передают эту вещь третьему лицу, принимающему на себя обязанность по разрешении спора возвратить вещь тому лицу, которому она будет присуждена по решению суда либо по соглашению всех спорящих лиц (договорный секвестр).\n\n2. Вещь, являющаяся предметом спора между двумя или несколькими лицами, может быть передана на хранение в порядке секвестра по решению суда (судебный секвестр).\n\nХранителем по судебному секвестру может быть как лицо, назначенное судом, так и лицо, определяемое по взаимному согласию спорящих сторон. В обоих случаях требуется согласие хранителя, если законом не установлено иное.\n\n3. На хранение в порядке секвестра могут быть переданы как движимые, так и недвижимые вещи.\n\n4. Хранитель, осуществляющий хранение вещи в порядке секвестра, имеет право на вознаграждение за счет спорящих сторон, если договором или решением суда, которым установлен секвестр, не предусмотрено иное.\n\n(Дополнение главой - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 926. Хранение вещей, являющихся предметом спора (секвестр)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c22836a190798041994281fde963148ec004f58371ecbdef0797b12523e4c9ed"},{"code_id":"GK_RF_2","article_number":"926.1","version_date":"1994-11-30","article_text":"1. По договору условного депонирования (эскроу) депонент обязуется передать на депонирование эскроу-агенту имущество в целях исполнения обязательства депонента по его передаче другому лицу, в пользу которого осуществляется депонирование имущества (бенефициару), а эскроу-агент обязуется обеспечить сохранность этого имущества и передать его бенефициару при возникновении указанных в договоре оснований.\n\nДоговор эскроу заключается между депонентом, бенефициаром и эскроу-агентом и должен предусматривать срок депонирования имущества. Срок действия договора эскроу не может превышать пять лет. Договор эскроу, заключенный на больший срок или без указания срока, считается заключенным на пять лет.\n\nДоговор эскроу подлежит нотариальному удостоверению, за исключением случаев депонирования безналичных денежных средств и (или) бездокументарных ценных бумаг.\n\n2. При возникновении указанных в договоре эскроу оснований для передачи имущества бенефициару (в том числе при совершении бенефициаром или третьим лицом предусмотренных договором действий либо наступлении установленных договором срока или события) эскроу-агент обязан передать депонированное имущество бенефициару в соответствии с условиями договора эскроу. Если указанные в договоре эскроу основания передачи имущества бенефициару в течение срока действия договора эскроу не возникают, эскроу-агент обязан вернуть полученное имущество депоненту.\n\n3. Объектом депонирования могут быть движимые вещи (включая наличные деньги, документарные ценные бумаги и документы), безналичные денежные средства, бездокументарные ценные бумаги.\n\n4. После передачи объекта депонирования эскроу-агенту и в течение всего периода действия договора эскроу депонент не вправе распоряжаться данным имуществом, если иное не предусмотрено договором.\n\n5. Обязательство депонента по передаче бенефициару имущества считается исполненным с момента передачи этого имущества эскроу-агенту.\n\n6. Сторонами может быть заключен договор, на основании которого у эскроу-агента должно быть депонировано имущество, подлежащее передаче сторонами двустороннего договора друг другу (взаимное эскроу).","article_title":"Статья 926.1. Договор условного депонирования (эскроу)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb81e3bb93c44afdb4e5c47a04dcc35b3c290b6256c8b5cb5f48f00be9017537"},{"code_id":"GK_RF_2","article_number":"926.2","version_date":"1994-11-30","article_text":"1. Эскроу-агент вправе требовать уплаты вознаграждения за исполнение своих обязательств, если иное не предусмотрено договором.\n\nОбязательство депонента и бенефициара по уплате вознаграждения эскроу-агенту является солидарным, если иное не предусмотрено договором.\n\n2. Эскроу-агент не вправе засчитывать или удерживать полученное от депонента имущество в счет оплаты или обеспечения оплаты своего вознаграждения, если иное не предусмотрено договором.","article_title":"Статья 926.2. Вознаграждение эскроу-агента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e81269b11ab88e1c2c88486d88fe71d7639f2056a6ceee5a5d8ee8cfbcf434b8"},{"code_id":"GK_RF_2","article_number":"926.3","version_date":"1994-11-30","article_text":"1. Если договором эскроу предусмотрена необходимость предъявления бенефициаром документов, подтверждающих возникновение оснований для передачи ему имущества, эскроу-агент обязан проверить их по внешним признакам и при наличии разумных оснований полагать, что представленные документы являются недостоверными, воздержаться от передачи имущества, если иное не предусмотрено договором.\n\n2. Договором эскроу может быть предусмотрена обязанность эскроу-агента проверить наличие оснований для передачи имущества бенефициару.","article_title":"Статья 926.3. Проверка оснований для передачи имущества бенефициару","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e8dd5937258d9273d99c2ddfb17eb996c2d7bba859c3a159d6a5592fb387ef2b"},{"code_id":"GK_RF_2","article_number":"926.4","version_date":"1994-11-30","article_text":"1. Имущество, переданное на депонирование эскроу-агенту, должно быть обособлено от его имущества. Это имущество отражается на отдельном балансе и (или) по нему ведется обособленный учет.\n\n2. Смешение эскроу-агентом переданного ему на депонирование имущества с иным (в том числе своим) имуществом того же рода не прекращает обязательства эскроу-агента перед депонентом и бенефициаром.\n\n3. Если иное не предусмотрено договором или не вытекает из существа обязательства, эскроу-агент не вправе использовать переданное ему на депонирование имущество и распоряжаться им.","article_title":"Статья 926.4. Обособление депонированного имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bc006ee427630996b5325621c41c0be14de854d07a38047c2931575ce4090a9"},{"code_id":"GK_RF_2","article_number":"926.5","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом, в случае передачи на депонирование вещей депонент сохраняет право собственности на них до даты возникновения оснований для их передачи бенефициару, а после указанной даты право собственности на депонированные вещи переходит к бенефициару.\n\n2. Эскроу-агент отвечает за утрату, недостачу или повреждение переданных ему на депонирование вещей, если не докажет, что эти обстоятельства произошли вследствие непреодолимой силы, либо из-за свойств вещей, о которых эскроу-агент, принимая их на депонирование, не знал и не должен был знать, либо в результате умысла или грубой неосторожности депонента.\n\n3. К отношениям по договору эскроу, предусматривающему передачу на депонирование вещей, право собственности на которые сохраняется за депонентом, применяются положения главы 47 настоящего Кодекса, если иное не предусмотрено правилами настоящей главы, договором или не вытекает из существа обязательства.","article_title":"Статья 926.5. Особенности депонирования вещей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b73a8ee84111f4c310ac99c6adf6234a589b748dca0e74af7df0f12af08525b3"},{"code_id":"GK_RF_2","article_number":"926.6","version_date":"1994-11-30","article_text":"1. При депонировании бездокументарных ценных бумаг запись об обременении таких ценных бумаг осуществляется в соответствии с правилами пункта 3 статьи 1492 настоящего Кодекса. Иной порядок и особенности депонирования бездокументарных ценных бумаг могут быть установлены законом о рынке ценных бумаг.\n\n2. Эскроу-агент не вправе распоряжаться депонированными бездокументарными ценными бумагами и осуществлять права по таким ценным бумагам, если иное не предусмотрено договором.\n\n3. Если эскроу-агент не является банком, безналичные денежные средства депонируются на его номинальном счете. Бенефициаром по номинальному счету, открытому эскроу-агенту, является депонент до даты возникновения оснований для передачи имущества бенефициару, предусмотренных договором эскроу, а после указанной даты бенефициаром по номинальному счету является бенефициар по договору эскроу.","article_title":"Статья 926.6. Особенности депонирования бездокументарных ценных бумаг и безналичных денежных средств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2aa5cd33a65c0de0b93b13e8db73434f8874f1abce44bd6f1bfa429a3d46801a"},{"code_id":"GK_RF_2","article_number":"926.7","version_date":"1994-11-30","article_text":"1. Обращение взыскания на депонированное имущество, арест такого имущества или принятие в отношении его обеспечительных мер по долгам эскроу-агента либо депонента не допускается.\n\n2. Взыскание по долгам депонента может быть обращено на право (требование) депонента к бенефициару или к эскроу-агенту в случаях прекращения договора эскроу либо нарушения обязательств по нему. При открытии номинального счета для целей депонирования безналичных денежных средств (пункт 3 статьи 9266) не применяются правила статьи 8605 об аресте или о списании денежных средств.\n\n3. По долгам бенефициара взыскание может быть обращено на его право (требование) к эскроу-агенту о передаче депонированного имущества.","article_title":"Статья 926.7. Особенности обращения взыскания на имущество по требованиям к сторонам договора эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ebf8a43e50dc5a1abd3b8dafef30a3b39f5160f0588f60357e34eedcc183e7a"},{"code_id":"GK_RF_2","article_number":"926.8","version_date":"1994-11-30","article_text":"1. Договор эскроу прекращается вследствие смерти гражданина, являющегося эскроу-агентом, признания его недееспособным, ограниченно дееспособным или безвестно отсутствующим, прекращения полномочий нотариуса, являющегося эскроу-агентом, ликвидации эскроу-агента, являющегося юридическим лицом, истечения срока договора эскроу, а также по иным предусмотренным настоящим Кодексом основаниям.\n\nДепонент и бенефициар могут отказаться от договора эскроу, направив совместное уведомление об этом эскроу-агенту в письменной форме или иным способом, предусмотренным договором эскроу.\n\n2. При прекращении договора эскроу депонированное имущество, если иное не предусмотрено соглашением депонента и бенефициара, подлежит возврату депоненту, а при возникновении оснований для передачи этого имущества бенефициару подлежит передаче бенефициару.\n\n3. Если договор эскроу до наступления предусмотренных настоящей статьей обстоятельств не был передан другому лицу (статья 3923), депонированное имущество подлежит возврату депоненту, а при возникновении оснований для передачи этого имущества бенефициару подлежит передаче бенефициару.","article_title":"Статья 926.8. Прекращение договора эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"09ab628a6d97ef5d7287c6a2d964d9904b1d47d9abc2b38e00d2ffc8646afee8"},{"code_id":"GK_RF_2","article_number":"927","version_date":"1994-11-30","article_text":"Абзац. (Утратил силу - Федеральный закон от 13.06.2023 № 209-ФЗ)","article_title":"Статья 927. Добровольное и обязательное страхование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2493274815cefd5ce2802e65443b59142f6b305df612d769f80c951dca64956"},{"code_id":"GK_RF_2","article_number":"928","version_date":"1994-11-30","article_text":"1. Страхование противоправных интересов не допускается.\n\n2. Не допускается страхование убытков от участия в играх, лотереях и пари.\n\n3. Не допускается страхование расходов, к которым лицо может быть принуждено в целях освобождения заложников.\n\n4. Условия договоров страхования, противоречащие пунктам 1 - 3 настоящей статьи, ничтожны.","article_title":"Статья 928. Интересы, страхование которых не допускается","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4149201f4aece24fdfa4c8a4f7d125a19bbac33ed9eebff68bb3f5589605fd1e"},{"code_id":"GK_RF_2","article_number":"929","version_date":"1994-11-30","article_text":"1. По договору имущественного страхования одна сторона (страховщик) обязуется за обусловленную договором плату (страховую премию) при наступлении предусмотренного в договоре события (страхового случая) возместить другой стороне (страхователю) или иному лицу, в пользу которого заключен договор (выгодоприобретателю), причиненные вследствие этого события убытки в застрахованном имуществе либо убытки в связи с иными имущественными интересами страхователя (выплатить страховое возмещение) в пределах определенной договором суммы (страховой суммы).\n\n2. По договору имущественного страхования могут быть, в частности, застрахованы следующие имущественные интересы:\n\n1) риск утраты (гибели), недостачи или повреждения определенного имущества (статья 930);\n\n2) риск ответственности по обязательствам, возникающим вследствие причинения вреда жизни, здоровью или имуществу других лиц, а в случаях, предусмотренных законом, также ответственности по договорам - риск гражданской ответственности (статьи 931 и 932);\n\n3) риск убытков от предпринимательской деятельности из-за нарушения своих обязательств контрагентами предпринимателя или изменения условий этой деятельности по не зависящим от предпринимателя обстоятельствам, в том числе риск неполучения ожидаемых доходов - предпринимательский риск (статья 933).","article_title":"Статья 929. Договор имущественного страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"923caa766ecc7d3efd8f61e9f119290fbe4b1e6538028371d63ad1217a358b9c"},{"code_id":"GK_RF_2","article_number":"930","version_date":"1994-11-30","article_text":"1. Имущество может быть застраховано по договору страхования в пользу лица (страхователя или выгодоприобретателя), имеющего основанный на законе, ином правовом акте или договоре интерес в сохранении этого имущества.\n\n2. Договор страхования имущества, заключенный при отсутствии у страхователя или выгодоприобретателя интереса в сохранении застрахованного имущества, недействителен.\n\n3. Договор страхования имущества в пользу выгодоприобретателя может быть заключен без указания имени или наименования выгодоприобретателя (страхование \"за счет кого следует\").\n\nПри заключении такого договора страхователю выдается страховой полис на предъявителя. При осуществлении страхователем или выгодоприобретателем прав по такому договору необходимо представление этого полиса страховщику.","article_title":"Статья 930. Страхование имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f59712a3b1a69a23b94f4e98d7ae98c897ff40ff42facd000238f5568b855d6"},{"code_id":"GK_RF_2","article_number":"931","version_date":"1994-11-30","article_text":"1. По договору страхования риска ответственности по обязательствам, возникающим вследствие причинения вреда жизни, здоровью или имуществу других лиц, может быть застрахован риск ответственности самого страхователя или иного лица, на которое такая ответственность может быть возложена.\n\n2. Лицо, риск ответственности которого за причинение вреда застрахован, должно быть названо в договоре страхования. Если это лицо в договоре не названо, считается застрахованным риск ответственности самого страхователя.\n\n3. Договор страхования риска ответственности за причинение вреда считается заключенным в пользу лиц, которым может быть причинен вред (выгодоприобретателей), даже если договор заключен в пользу страхователя или иного лица, ответственных за причинение вреда, либо в договоре не сказано, в чью пользу он заключен.\n\n4. В случае, когда ответственность за причинение вреда застрахована в силу того, что ее страхование обязательно, а также в других случаях, предусмотренных законом или договором страхования такой ответственности, лицо, в пользу которого считается заключенным договор страхования, вправе предъявить непосредственно страховщику требование о возмещении вреда в пределах страховой суммы.","article_title":"Статья 931. Страхование ответственности за причинение вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a62088ae96327a94127d5f51eef918085671f6c4bc283f9ee625046045be78a6"},{"code_id":"GK_RF_2","article_number":"932","version_date":"1994-11-30","article_text":"1. Страхование риска ответственности за нарушение договора допускается в случаях, предусмотренных законом.\n\n2. По договору страхования риска ответственности за нарушение договора может быть застрахован только риск ответственности самого страхователя. Договор страхования, не соответствующий этому требованию, ничтожен.\n\n3. Риск ответственности за нарушение договора считается застрахованным в пользу стороны, перед которой по условиям этого договора страхователь должен нести соответствую\n\nщую ответственность, - выгодоприобретателя, даже если договор страхования заключен в пользу другого лица либо в нем не сказано, в чью пользу он заключен.","article_title":"Статья 932. Страхование ответственности по договору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"39fa3e5580be8ec5289a83b6e7610f4d2c25da8509a27b46fdf207306871e917"},{"code_id":"GK_RF_2","article_number":"933","version_date":"1994-11-30","article_text":"По договору страхования предпринимательского риска может быть застрахован предпринимательский риск только самого страхователя и только в его пользу.\n\nДоговор страхования предпринимательского риска лица, не являющегося страхователем, ничтожен.\n\nДоговор страхования предпринимательского риска в пользу лица, не являющегося страхователем, считается заключенным в пользу страхователя.","article_title":"Статья 933. Страхование предпринимательского риска","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"32cf904d92d7385c0500d8f855a09997aa2c55f0730879b75c4cb4463cbe36ef"},{"code_id":"GK_RF_2","article_number":"934","version_date":"1994-11-30","article_text":"1. По договору личного страхования одна сторона (страховщик) обязуется за обусловленную договором плату (страховую премию), уплачиваемую другой стороной (страхователем), выплатить единовременно или выплачивать периодически обусловленную договором сумму (страховую сумму) в случае причинения вреда жизни или здоровью самого страхователя или другого названного в договоре гражданина (застрахованного лица), достижения им определенного возраста или наступления в его жизни иного предусмотренного договором события (страхового случая).\n\nПраво на получение страховой суммы принадлежит лицу, в пользу которого заключен договор.\n\n2. Договор личного страхования считается заключенным в пользу застрахованного лица, если в договоре не названо в качестве выгодоприобретателя другое лицо. В случае смерти лица, застрахованного по договору, в котором не назван иной выгодоприобретатель, выгодоприобретателями признаются наследники застрахованного лица.\n\nДоговор личного страхования в пользу лица, не являющегося застрахованным лицом, в том числе в пользу не являющегося застрахованным лицом страхователя, может быть заключен лишь с письменного согласия застрахованного лица. При отсутствии такого согласия договор может быть признан недействительным по иску застрахованного лица, а в случае смерти этого лица по иску его наследников.","article_title":"Статья 934. Договор личного страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fca48ced45a87b2a2823ee560654d9258d2933c1e157f4b57e4c765767a01ed6"},{"code_id":"GK_RF_2","article_number":"935","version_date":"1994-11-30","article_text":"1. Законом на указанных в нем лиц может быть возложена обязанность страховать:\n\nжизнь, здоровье или имущество других определенных в законе лиц на случай причинения вреда их жизни, здоровью или имуществу;\n\nриск своей гражданской ответственности, которая может наступить вследствие причинения вреда жизни, здоровью или имуществу других лиц или нарушения договоров с другими лицами.\n\n2. Обязанность страховать свою жизнь или здоровье не может быть возложена на гражданина по закону.\n\n3. В случаях, предусмотренных законом или в установленном им порядке, на юридических лиц, имеющих в хозяйственном ведении или оперативном управлении имущество, являющееся государственной или муниципальной собственностью, может быть возложена обязанность страховать это имущество.","article_title":"Статья 935. Обязательное страхование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bf0020b3bff38df24e9499b9a08d6d498747a9727a1f643e0a818941f428f713"},{"code_id":"GK_RF_2","article_number":"936","version_date":"1994-11-30","article_text":"1. Обязательное страхование осуществляется путем заключения договора страхования лицом, на которое возложена обязанность такого страхования (страхователем), со страховщиком.","article_title":"Статья 936. Осуществление обязательного страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40cf7bb800d63555b521ac1cd142ec592bc2f737c0868aabe6b968f68a73622c"},{"code_id":"GK_RF_2","article_number":"937","version_date":"1994-11-30","article_text":"1. Лицо, в пользу которого по закону должно быть осуществлено обязательное страхование, вправе, если ему известно, что страхование не осуществлено, потребовать в судебном порядке его осуществления лицом, на которое возложена обязанность страхования.\n\n2. Если лицо, на которое возложена обязанность страхования, не осуществило его или заключило договор страхования на условиях, ухудшающих положение выгодоприобретателя по сравнению с условиями, определенными законом, оно при наступлении страхового случая несет ответственность перед выгодоприобретателем на тех же условиях, на каких должно было быть выплачено страховое возмещение при надлежащем страховании.","article_title":"Статья 937. Последствия нарушения правил об обязательном страховании","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bbb6b564a5c831c5bdac79eb588d8657296e4328bab42a77ae1adad28ce03d2f"},{"code_id":"GK_RF_2","article_number":"938","version_date":"1994-11-30","article_text":"В качестве страховщиков договоры страхования могут заключать юридические лица, имеющие разрешения (лицензии) на осуществление страхования соответствующего вида.\n\nТребования, которым должны отвечать страховщики, порядок лицензирования их деятельности и осуществления надзора за этой деятельностью определяются законами о страховании. (В редакции федеральных законов от 23.07.2013 № 251-ФЗ, от 01.07.2021 № 295-ФЗ)","article_title":"Статья 938. Страховщик","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1fcb49c1d45d902a1460baf720e7ce2dcbac0459c1593ca30e73dd90adc514ed"},{"code_id":"GK_RF_2","article_number":"939","version_date":"1994-11-30","article_text":"1. Заключение договора страхования в пользу выгодоприобретателя, в том числе и тогда, когда им является застрахованное лицо, не освобождает страхователя от выполнения обязанностей по этому договору, если только договором не предусмотрено иное либо обязанности страхователя выполнены лицом, в пользу которого заключен договор.\n\n2. Страховщик вправе требовать от выгодоприобретателя, в том числе и тогда, когда выгодоприобретателем является застрахованное лицо, выполнения обязанностей по договору страхования, включая обязанности, лежащие на страхователе, но не выполненные им, при предъявлении выгодоприобретателем требования о выплате страхового возмещения по договору имущественного страхования либо страховой суммы по договору личного страхования. Риск последствий невыполнения или несвоевременного выполнения обязанностей, которые должны были быть выполнены ранее, несет выгодоприобретатель.","article_title":"Статья 939. Выполнение обязанностей по договору страхования страхователем и выгодоприобретателем","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"405396e8f51b2b8e6faf237d55bfbe49ba77aacee3ec97dda3a9902ee7a0a123"},{"code_id":"GK_RF_2","article_number":"940","version_date":"1994-11-30","article_text":"1. Договор страхования должен быть заключен в письменной форме.\n\nНесоблюдение письменной формы влечет недействительность договора страхования, за исключением договора обязательного государственного страхования (статья 969).\n\nВ последнем случае согласие страхователя заключить договор на предложенных страховщиком условиях подтверждается принятием от страховщика указанных в абзаце первом настоящего пункта документов.\n\nДоговор страхования может быть также заключен путем составления одного электронного документа, подписанного сторонами, или обмена электронными документами либо иными данными в соответствии с правилами абзаца второго пункта 1 статьи 160 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 18.03.2019 № 34-ФЗ)","article_title":"Статья 940. Форма договора страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69cacece311547020f30db0f8a1c8e35f60f79c40552a1b8959856230ee7dc26"},{"code_id":"GK_RF_2","article_number":"941","version_date":"1994-11-30","article_text":"1. Систематическое страхование разных партий однородного имущества (товаров, грузов и т.п.) на сходных условиях в течение определенного срока может по соглашению страхователя со страховщиком осуществляться на основании одного договора страхования - генерального полиса.\n\n2. Страхователь обязан в отношении каждой партии имущества, подпадающей под действие генерального полиса, сообщать страховщику обусловленные таким полисом сведения в предусмотренный им срок, а если он не предусмотрен, немедленно по их получении. Страхователь не освобождается от этой обязанности, даже если к моменту получения таких сведений возможность убытков, подлежащих возмещению страховщиком, уже миновала.\n\n3. По требованию страхователя страховщик обязан выдавать страховые полисы по отдельным партиям имущества, подпадающим под действие генерального полиса.\n\nВ случае несоответствия содержания страхового полиса генеральному полису предпочтение отдается страховому полису.","article_title":"Статья 941. Страхование по генеральному полису","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2142f23e804440a7fc22af583ae23149cc7475a39039f4db5f479aeca461898"},{"code_id":"GK_RF_2","article_number":"942","version_date":"1994-11-30","article_text":"1. При заключении договора имущественного страхования между страхователем и страховщиком должно быть достигнуто соглашение:\n\n1) об определенном имуществе либо ином имущественном интересе, являющемся объектом страхования;\n\n2) о характере события, на случай наступления которого осуществляется страхование (страхового случая);\n\n3) о размере страховой суммы;\n\n4) о сроке действия договора.\n\n2. При заключении договора личного страхования между страхователем и страховщиком должно быть достигнуто соглашение:\n\n1) о застрахованном лице;\n\n2) о характере события, на случай наступления которого в жизни застрахованного лица осуществляется страхование (страхового случая);\n\n3) о размере страховой суммы;\n\n4) о сроке действия договора.","article_title":"Статья 942. Существенные условия договора страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"95849af3ca66f95c4b6dc46c8c6991b056eb6ee60365e96386449e877c160bd2"},{"code_id":"GK_RF_2","article_number":"943","version_date":"1994-11-30","article_text":"1. Условия, на которых заключается договор страхования, могут быть определены в стандартных правилах страхования соответствующего вида, принятых, одобренных или утвержденных страховщиком либо объединением страховщиков (правилах страхования).\n\n2. Условия, содержащиеся в правилах страхования и не включенные в текст договора страхования (страхового полиса), обязательны для страхователя (выгодоприобретателя), если в договоре (страховом полисе) прямо указывается на применение таких правил и сами правила изложены в одном документе с договором (страховым полисом) или на его оборотной стороне либо приложены к нему. В последнем случае вручение страхователю при заключении договора правил страхования должно быть удостоверено записью в договоре.\n\n3. При заключении договора страхования страхователь и страховщик могут договориться об изменении или исключении отдельных положений правил страхования и о дополнении правил.\n\n4. Страхователь (выгодоприобретатель) вправе ссылаться в защиту своих интересов на правила страхования соответствующего вида, на которые имеется ссылка в договоре страхования (страховом полисе), даже если эти правила в силу настоящей статьи для него необязательны.","article_title":"Статья 943. Определение условий договора страхования в правилах страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fa88f2a826d75cc6d315fd47a4f50e7be09dd25c564dec50d6b7578c5bf9e01c"},{"code_id":"GK_RF_2","article_number":"944","version_date":"1994-11-30","article_text":"1. При заключении договора страхования страхователь обязан сообщить страховщику известные страхователю обстоятельства, имеющие существенное значение для определения вероятности наступления страхового случая и размера возможных убытков от его наступления (страхового риска), если эти обстоятельства не известны и не должны быть известны страховщику.\n\nСущественными признаются во всяком случае обстоятельства, определенно оговоренные страховщиком в стандартной форме договора страхования (страхового полиса) или в его письменном запросе.\n\n2. Если договор страхования заключен при отсутствии ответов страхователя на какие-либо вопросы страховщика, страховщик не может впоследствии требовать расторжения договора либо признания его недействительным на том основании, что соответствующие обстоятельства не были сообщены страхователем.\n\n3. Если после заключения договора страхования будет установлено, что страхователь сообщил страховщику заведомо ложные сведения об обстоятельствах, указанных в пункте 1 настоящей статьи, страховщик вправе потребовать признания договора недействительным и применения последствий, предусмотренных пунктом 2 статьи 179 настоящего Кодекса.\n\nСтраховщик не может требовать признания договора страхования недействительным, если обстоятельства, о которых умолчал страхователь, уже отпали.","article_title":"Статья 944. Сведения, предоставляемые страхователем при заключении договора страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e06349af1d5a97424e269968b30b245da09b9c6efdd84105140aaad82b7125b5"},{"code_id":"GK_RF_2","article_number":"945","version_date":"1994-11-30","article_text":"1. При заключении договора страхования имущества страховщик вправе произвести осмотр страхуемого имущества, а при необходимости назначить экспертизу в целях установления его действительной стоимости.\n\n2. При заключении договора личного страхования страховщик вправе провести обследование страхуемого лица для оценки фактического состояния его здоровья.\n\n3. Оценка страхового риска страховщиком на основании настоящей статьи необязательна для страхователя, который вправе доказывать иное.","article_title":"Статья 945. Право страховщика на оценку страхового риска","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aea29f35fe77aaed899756db847d1809c1c69c29751f18dc2fd098803d2b7b71"},{"code_id":"GK_RF_2","article_number":"946","version_date":"1994-11-30","article_text":"Страховщик не вправе разглашать полученные им в результате своей профессиональной деятельности сведения о страхователе, застрахованном лице и выгодоприобретателе, состоянии их здоровья, а также об имущественном положении этих лиц. За нарушение тайны страхования страховщик в зависимости от рода нарушенных прав и характера нарушения несет ответственность в соответствии с правилами, предусмотренными статьей 139 или статьей 150 настоящего Кодекса.","article_title":"Статья 946. Тайна страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0362632b3b84469beecb933bda7ddc1d9c65f5b839eff835969ed57de5bb5b6"},{"code_id":"GK_RF_2","article_number":"947","version_date":"1994-11-30","article_text":"1. Сумма, в пределах которой страховщик обязуется выплатить страховое возмещение по договору имущественного страхования или которую он обязуется выплатить по договору личного страхования (страховая сумма), определяется соглашением страхователя со страховщиком в соответствии с правилами, предусмотренными настоящей статьей.\n\n2. При страховании имущества или предпринимательского риска, если договором страхования не предусмотрено иное, страховая сумма не должна превышать их действительную стоимость (страховой стоимости). Такой стоимостью считается:\n\nдля имущества его действительная стоимость в месте его нахождения в день заключения договора страхования;\n\nдля предпринимательского риска убытки от предпринимательской деятельности, которые страхователь, как можно ожидать, понес бы при наступлении страхового случая.\n\n3. В договорах личного страхования и договорах страхования гражданской ответственности страховая сумма определяется сторонами по их усмотрению.","article_title":"Статья 947. Страховая сумма","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"859575e570249a876fb5cf81f1bb03bc5560a3f7d6cfd5ebd29438aeeb80013c"},{"code_id":"GK_RF_2","article_number":"948","version_date":"1994-11-30","article_text":"Страховая стоимость имущества, указанная в договоре страхования, не может быть впоследствии оспорена, за исключением случая, когда страховщик, не воспользовавшийся до заключения договора своим правом на оценку страхового риска (пункт 1 статьи 945), был умышленно введен в заблуждение относительно этой стоимости.","article_title":"Статья 948. Оспаривание страховой стоимости имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b3fbabb6fb246334a33f4f369bb83c5d03b521dbce21a066b5c4932e4bdf68cf"},{"code_id":"GK_RF_2","article_number":"949","version_date":"1994-11-30","article_text":"Если в договоре страхования имущества или предпринимательского риска страховая сумма установлена ниже страховой стоимости, страховщик при наступлении страхового случая обязан возместить страхователю (выгодоприобретателю) часть понесенных последним убытков пропорционально отношению страховой суммы к страховой стоимости.\n\nДоговором может быть предусмотрен более высокий размер страхового возмещения, но не выше страховой стоимости.","article_title":"Статья 949. Неполное имущественное страхование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a98796e9913b4cb41e14d8be01aaf0ad58ae552b0ab2b91c1179901317a5ca71"},{"code_id":"GK_RF_2","article_number":"950","version_date":"1994-11-30","article_text":"1. В случае, когда имущество или предпринимательский риск застрахованы лишь в части страховой стоимости, страхователь (выгодоприобретатель) вправе осуществить дополнительное страхование, в том числе у другого страховщика, но с тем, чтобы общая страховая сумма по всем договорам страхования не превышала страховую стоимость.\n\n2. Несоблюдение положений пункта 1 настоящей статьи влечет последствия, предусмотренные пунктом 4 статьи 951 настоящего Кодекса.","article_title":"Статья 950. Дополнительное имущественное страхование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e1504e4fa9ab99ebb7fe155ae74fc10cf050a1863dfc689a917396b5f159352"},{"code_id":"GK_RF_2","article_number":"951","version_date":"1994-11-30","article_text":"1. Если страховая сумма, указанная в договоре страхования имущества или предпринимательского риска, превышает страховую стоимость, договор является ничтожным в той части страховой суммы, которая превышает страховую стоимость.\n\nУплаченная излишне часть страховой премии возврату в этом случае не подлежит.\n\n2. Если в соответствии с договором страхования страховая премия вносится в рассрочку и к моменту установления обстоятельств, указанных в пункте 1 настоящей статьи, она внесена не полностью, оставшиеся страховые взносы должны быть уплачены в размере, уменьшенном пропорционально уменьшению размера страховой суммы.\n\n3. Если завышение страховой суммы в договоре страхования явилось следствием обмана со стороны страхователя, страховщик вправе требовать признания договора недействительным и возмещения причиненных ему этим убытков в размере, превышающем сумму полученной им от страхователя страховой премии.\n\n4. Правила, предусмотренные в пунктах 1 - 3 настоящей статьи, соответственно применяются и в том случае, когда страховая сумма превысила страховую стоимость в результате страхования одного и того же объекта у двух или нескольких страховщиков (двойное страхование).\n\nСумма страхового возмещения, подлежащая выплате в этом случае каждым из страховщиков, сокращается пропорционально уменьшению первоначальной страховой суммы по соответствующему договору страхования.","article_title":"Статья 951. Последствия страхования сверх страховой стоимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3942691d9dc36a338f8c7b9cf0ec0794d91050aeee3f129fe4fc9ede205222e2"}]$law7d0038$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
